void check(bool b,const char* why){if(!b)throw std::runtime_error(why);}
template<class F>void rejects(F f){bool threw=false;try{f();}catch(const std::exception&){threw=true;}check(threw,"Invalid model accepted");}
void wav(const fs::path& p,unsigned rate=48000){fs::create_directories(p.parent_path());std::ofstream o(p,std::ios::binary);auto word=[&](unsigned v,int n){for(int i=0;i<n;++i)o.put(static_cast<char>(v>>(8*i)));};const auto frames=rate/5;o.write("RIFF",4);word(36+frames*2,4);o.write("WAVEfmt ",8);word(16,4);word(1,2);word(1,2);word(rate,4);word(rate*2,4);word(2,2);word(16,2);o.write("data",4);word(frames*2,4);for(unsigned j=0;j<frames;++j)word(j==0?10000:0,2);}
