    if(argc==3&&std::string_view(argv[1])=="--polytone"){auto catalog=scan_cab_collection(fs::path(std::u8string(reinterpret_cast<const char8_t*>(argv[2]))),"polytone");std::vector<std::string> all;for(const auto& a:catalog.assets){check(a.error.empty(),"Invalid real WAV");all.push_back(a.relative);}map_cab_assets(catalog,all,{{"ir_role","full_combo"},{"amp_make","Polytone"},{"amp_model","Mini Brute"},{"provenance","user assigned"}},"_441");ToneLibrary library;curate_cab_manifest(library,catalog);check(library.models.size()==10&&library.sources.size()==20,"20 rate variants must form 10 captures");for(const auto& m:library.models){check(m.role=="full_combo"&&m.sources.size()==2,"Real capture role/rates");for(auto rate:{44100u,48000u,96000u})check(tone_source_available(*tone_source(library,m,rate)),"Actual source integrity");}check(deserialize_tone_library(serialize_tone_library(library))==library,"Real model roundtrip");check(tone_variants(library,library.models.front()).size()==10,"One Polytone family with ten captures");std::cout<<"Polytone read-only: 1 model / 10 captures / 20 sources PASS\n";return 0;}
    const auto root=fs::temp_directory_path()/fs::path("mrs-tone-"+mrs::new_id().value);check(!fs::exists(root),"Fixture scope");fs::create_directories(root);struct Cleanup{fs::path p;~Cleanup(){fs::remove_all(p);}}cleanup{root};
    const auto first=root/fs::path(u8"Зал/Combo.wav");wav(first);wav(root/fs::path(u8"Зал/Combo_441.wav"),44100);wav(root/"Cab.wav");wav(root/"Unknown.wav");
    auto catalog=scan_cab_collection(root,"test");map_cab_assets(catalog,{"Зал/Combo.wav","Зал/Combo_441.wav"},{{"ir_role","full_combo"},{"amp_make","Maker"},{"amp_model","Test"}},"_441");map_cab_assets(catalog,{"Cab.wav"},{{"ir_role","cabinet"}});
    ToneLibrary lib;curate_cab_manifest(lib,catalog);check(lib.models.size()==3&&lib.sources.size()==4,"Model/source distinction and capture grouping");auto combo=std::find_if(lib.models.begin(),lib.models.end(),[](const auto& m){return m.role=="full_combo";});check(combo!=lib.models.end(),"Full Combo role");const auto id=combo->id;combo->title="My Jazz";combo->tags={"Jazz","Clean"};combo->favorite=true;
    check(tone_source(lib,*combo,44100)->rate==44100&&tone_source(lib,*combo,48000)->rate==48000,"Exact rate alternatives");
    check(combo->family_title=="Maker Test"&&tone_variants(lib,*combo).size()==1,"Explicit model identity, independent from edited capture title");
    combo->preferred=true;
    const auto saved=serialize_tone_library(lib);check(deserialize_tone_library(saved)==lib,"Metadata roundtrip");curate_cab_manifest(lib,catalog);check(serialize_tone_library(lib)==saved,"Reindex preserves manual curation and IDs");
    auto another=catalog;another.collection_id="import-another-id";for(auto& a:another.assets){a.id="again:"+a.id;a.variant_id="again:"+a.variant_id;}curate_cab_manifest(lib,another);check(lib.models.size()==3&&lib.sources.size()==4,"Importing the same exact files does not duplicate cards");
    auto source=*tone_source(lib,*std::find_if(lib.models.begin(),lib.models.end(),[&](const auto& m){return m.id==id;}),48000);check(tone_source_available(source),"Installed source verification");
    auto fallback=source;fallback.root=(root/"missing-root").generic_string();check(tone_source_available(fallback),"Absolute fallback resolves a missing original root");auto wrongFormat=source;wrongFormat.rate=44100;check(!tone_source_available(wrongFormat),"Installed source must match its actual WAV metadata");
    const auto moved=root/"moved";fs::create_directories(moved);fs::rename(first,moved/"Combo.wav");check(!tone_source_available(source),"Missing source detected without substitution");auto relocated=scan_cab_collection(moved,"moved");const auto sourceId=source.id;relink_tone_source(source,relocated,relocated.assets.front());check(source.id==sourceId&&tone_source_available(source),"Same-content relink keeps identity");auto bad=relocated.assets.front();bad.digest="different";rejects([&]{relink_tone_source(source,relocated,bad);});check(tone_source_available(source),"Failed relink leaves source intact");
