    for(const auto* name:{"A","B"})legacy<<std::quoted(std::string("old:")+name)<<' '<<std::quoted(std::string("Mini Brute / ")+name)<<" \"Polytone\" "<<std::quoted(name)<<" 0 \"full_combo\" \"userAssigned\" 0 \"\" \"\" \"\" 1 "<<std::quoted(source.id)<<" 0\n";
    const auto upgraded=deserialize_tone_library(legacy.str());check(tone_variants(upgraded,upgraded.models.front()).size()==2&&upgraded.models.front().family_title=="Polytone Mini Brute","Existing generated v1 capture bookmarks become one amplifier card");
    auto truncated=saved;while(!truncated.empty()&&std::isspace(static_cast<unsigned char>(truncated.back())))truncated.pop_back();truncated.pop_back();rejects([&]{deserialize_tone_library(truncated);});
